function findUser(users, id) {
  for (let i = 0; i < users.length; i++) {
    if (users[i].id === id) {
      return users[i]
    }
  }
  return null
}

const users = [{ id: 1, name: 'Alice' }, { id: 2, name: 'Bob' }]
const userId = '2' // from URL query param, always a string

console.log(findUser(users, userId)) // returns null, not Bob
